from pathlib import Path
root=Path('/workspace/source/src')
hits=[]
for p in root.rglob('*.java'):
    if 'practical-runtime' in str(p):
        continue
    try:
        text=p.read_text(errors='replace')
    except Exception:
        continue
    if 'removeChildren' in text:
        for i,l in enumerate(text.splitlines(),1):
            if 'removeChildren' in l:
                hits.append(f'{p}:{i}:{l.strip()[:140]}')
print('HITS', len(hits))
print('\n'.join(hits[:40]))
